function chapterArtwork(entries){for(const line of entries){const scene=D.events.find(e=>e.id===line.scene);if(AzureRemake.manifest.sceneBackgrounds?.[line.scene])return 'assets/hd/'+AzureRemake.manifest.sceneBackgrounds[line.scene]+'.webp';const name=scene?.backgrounds?.find(n=>AzureRemake.manifest.backgrounds[n]);if(name)return 'assets/hd/'+AzureRemake.manifest.backgrounds[name]+'.webp';}return 'assets/hd/title-background.webp';}
